        _sut.SendNotification("Student", "2", "Second", EntityOperation.CREATE);
        _sut.SendNotification("Student", "3", "Third", EntityOperation.CREATE);

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.Equal("1", first!.EntityId);
        Assert.Equal("New Student 'First' has been created", first.Message);

        var second = _sut.ReceiveNotification();
        Assert.Equal("2", second!.EntityId);

        var third = _sut.ReceiveNotification();
        Assert.Equal("3", third!.EntityId);
    }

    [Fact]
    public void SendNotification_QueueCapsAt500Items_OldestRemoved()
    {
        // Arrange - fill queue beyond capacity
        for (int i = 0; i < 505; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
        }

        // Act - drain all and count
        var notifications = new List<Notification>();
        Notification? n;
        while ((n = _sut.ReceiveNotification()) != null)
        {
            notifications.Add(n);
        }

        // Assert - should have at most 500 items
        Assert.True(notifications.Count <= 500);
        // The oldest items (0-4) should have been removed
        Assert.DoesNotContain(notifications, x => x.EntityId == "0");
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // Act & Assert - MarkAsRead is a no-op, should not throw
        var exception = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_DefaultUserName_IsSystem()
    {
        // Act
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.Equal("System", notification!.CreatedBy);
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_CorrectPageCalculation()
    {
        // Arrange - 25 items, page 2, pageSize 10
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(3, result.TotalPages); // ceil(25/10) = 3
        Assert.Equal(10, result.Count); // items on page 2
        Assert.Equal(11, result[0]); // first item on page 2
    }

    [Fact]
    public void HasPreviousPage_FalseOnPage1()
    {
        // Arrange
        var source = Enumerable.Range(1, 20).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_TrueOnPage2()
    {
        // Arrange
        var source = Enumerable.Range(1, 20).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_TrueWhenMorePagesExist()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FalseOnLastPage()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 3, 10);

        // Assert
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void TotalPages_CeilingCalculation()
    {
        // Arrange - 11 items with pageSize 5 => ceil(11/5) = 3
        var source = Enumerable.Range(1, 11).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 5);

        // Assert
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void TotalPages_ExactDivision()
    {
        // Arrange - 20 items with pageSize 10 => 2 pages exactly
        var source = Enumerable.Range(1, 20).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Equal(2, result.TotalPages);
    }

    [Fact]
    public void Create_FirstPage_ContainsCorrectItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 30).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_LastPage_ContainsRemainingItems()
    {
        // Arrange - 25 items, page 3 (page size 10) => 5 items
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 3, 10);

        // Assert
        Assert.Equal(5, result.Count);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }
}

