using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
            .Options;
        _context = new SchoolContext(options);
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { ID = 1, LastName = "Anderson", FirstMidName = "Alice", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { ID = 2, LastName = "Baker", FirstMidName = "Bob", EnrollmentDate = new DateTime(2022, 9, 1) },
            new Student { ID = 3, LastName = "Clark", FirstMidName = "Carol", EnrollmentDate = new DateTime(2024, 1, 15) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index(null, null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Anderson", model[0].LastName);
        Assert.Equal("Baker", model[1].LastName);
        Assert.Equal("Clark", model[2].LastName);
    }

    [Fact]
    public void Index_NameDesc_OrdersByLastNameDescending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Clark", model[0].LastName);
        Assert.Equal("Baker", model[1].LastName);
        Assert.Equal("Anderson", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Baker", model[0].LastName); // 2022
        Assert.Equal("Anderson", model[1].LastName); // 2023
        Assert.Equal("Clark", model[2].LastName); // 2024
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Clark", model[0].LastName); // 2024
        Assert.Equal("Anderson", model[1].LastName); // 2023
        Assert.Equal("Baker", model[2].LastName); // 2022
    }

    [Fact]
    public void Index_SearchFilter_FiltersByLastName()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index(null, null, "Baker", null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Baker", model[0].LastName);
    }

    [Fact]
    public void Index_SearchFilter_FiltersByFirstMidName()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index(null, null, "Alice", null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Anderson", model[0].LastName);
    }

    [Fact]
    public void Index_NewSearch_ResetsToPage1()
    {
        // Arrange
        SeedStudents();

        // Act - searchString is not null, so page should be set to 1
        var result = _controller.Index(null, null, "A", 3) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_UsesCurrentFilter_WhenSearchStringIsNull()
    {
        // Arrange
        SeedStudents();

        // Act - searchString is null, so currentFilter should be used
        var result = _controller.Index(null, "Baker", null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Baker", model[0].LastName);
    }

    [Fact]
    public void Details_ReturnsStatusCode400_WhenIdIsNull()
    {
        // Act
        var result = _controller.Details(null) as StatusCodeResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Details_ReturnsStudentWithEnrollments_WhenFound()
    {
        // Arrange
        var course = new Course { CourseID = 101, Title = "Math", Credits = 3, DepartmentID = 1 };
        _context.Courses.Add(course);
        var student = new Student { ID = 1, LastName = "Test", FirstMidName = "Student", EnrollmentDate = DateTime.Today };
        _context.Students.Add(student);
        _context.SaveChanges();
        _context.Enrollments.Add(new Enrollment { EnrollmentID = 1, CourseID = 101, StudentID = 1, Grade = Grade.A });
        _context.SaveChanges();

        // Act
        var result = _controller.Details(1) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal("Test", model.LastName);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    [Fact]
    public void Create_GET_ReturnsViewWithStudentHavingTodaysDate()
    {
        // Act
        var result = _controller.Create() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_POST_ValidStudent_SavesAndRedirects()
    {
        // Arrange
        var student = new Student
        {
            LastName = "NewStudent",
            FirstMidName = "First",
            EnrollmentDate = new DateTime(2024, 1, 15)
        };

        // Act
        var result = _controller.Create(student) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(_context.Students);
        Assert.Equal("NewStudent", _context.Students.First().LastName);
    }

    [Fact]
    public void Create_POST_InvalidEnrollmentDate_MinValue_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        // Act
        var result = _controller.Create(student) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_POST_DateOutOfSqlRange_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(1752, 12, 31) // before 1753
        };

        // Act
        var result = _controller.Create(student) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_POST_ExceptionDuringSave_AddsGenericError()
    {
        // Arrange - use a disposed context to trigger exception
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
            .Options;
        var context = new SchoolContext(options);
        var controller = new StudentsController(context);
        context.Dispose(); // Force exception on save

        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2024, 1, 15)
        };

        // Act
        var result = controller.Create(student) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.True(controller.ModelState.ContainsKey(""));
    }

    [Fact]
    public void Edit_GET_ReturnsStatusCode400_WhenIdIsNull()
    {
        // Act
        var result = _controller.Edit((int?)null) as StatusCodeResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Edit_GET_ReturnsNotFound_WhenStudentDoesNotExist()
    {
        // Act
        var result = _controller.Edit(999) as NotFoundResult;

        // Assert
        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_GET_ReturnsViewWithStudent_WhenFound()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Edit(1) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal("Anderson", model.LastName);
    }

    [Fact]
    public void Edit_POST_ValidUpdate_ModifiesAndRedirects()
    {
        // Arrange
        SeedStudents();
        var student = new Student
        {
            ID = 1,
            LastName = "UpdatedName",
            FirstMidName = "Alice",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        var result = _controller.Edit(student) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var updated = _context.Students.Find(1);
        Assert.Equal("UpdatedName", updated!.LastName);
    }

    [Fact]
    public void Edit_POST_InvalidDate_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            ID = 1,
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        // Act
        var result = _controller.Edit(student) as ViewResult;

        // Assert
