+using Microsoft.AspNetCore.Mvc;
+using Microsoft.EntityFrameworkCore;
+
+namespace ContosoUniversity.Tests.Controllers;
+
+public class NotificationsControllerTests : IDisposable
+{
+    private readonly SchoolContext _context;
+    private readonly NotificationsController _controller;
+    private readonly NotificationService _notificationService;
+
+    public NotificationsControllerTests()
+    {
+        var options = new DbContextOptionsBuilder<SchoolContext>()
+            .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
+            .Options;
+        _context = new SchoolContext(options);
+        _controller = new NotificationsController(_context);
+        _notificationService = new NotificationService();
+        // Drain the static queue to isolate tests
+        while (_notificationService.ReceiveNotification() != null) { }
+    }
+
+    public void Dispose()
+    {
+        // Drain queue
+        while (_notificationService.ReceiveNotification() != null) { }
+        _controller.Dispose();
+        _context.Dispose();
+        _notificationService.Dispose();
+    }
+
+    [Fact]
+    public void GetNotifications_ReturnsEmptyList_WhenQueueEmpty()
+    {
+        // Act
+        var result = _controller.GetNotifications();
+
+        // Assert
+        Assert.NotNull(result);
+        var value = result.Value as dynamic;
+        Assert.NotNull(value);
+        // Use reflection to check properties
+        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
+        Assert.Contains("\"success\":true", json);
+        Assert.Contains("\"count\":0", json);
+    }
+
+    [Fact]
+    public void GetNotifications_ReturnsUpTo10Notifications()
+    {
+        // Arrange - add 15 notifications
+        for (int i = 0; i < 15; i++)
+        {
+            _notificationService.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
+        }
+
+        // Act
+        var result = _controller.GetNotifications();
+
+        // Assert
+        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
+        Assert.Contains("\"count\":10", json);
+        Assert.Contains("\"success\":true", json);
+    }
+
+    [Fact]
+    public void GetNotifications_ReturnsSuccessWithNotificationData()
+    {
+        // Arrange
+        _notificationService.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);
+
+        // Act
+        var result = _controller.GetNotifications();
+
+        // Assert
+        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
+        Assert.Contains("\"success\":true", json);
+        Assert.Contains("\"count\":1", json);
+        Assert.Contains("Student", json);
+    }
+
+    [Fact]
+    public void MarkAsRead_ReturnsSuccessJson()
+    {
+        // Act
+        var result = _controller.MarkAsRead(1);
+
+        // Assert
+        var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
+        Assert.Contains("\"success\":true", json);
+    }
+
